WITH actual AS (SELECT 'da' src,count(*) n,sum(closing_value) total FROM marts.da_transactions WHERE closing_value>0 AND closing_value<=2000000 UNION ALL SELECT 'contracts',count(*),sum(closing_value) FROM marts.contract_transactions WHERE closing_value>0)
SELECT 'aggregate_vs_transactions' test,jsonb_agg(jsonb_build_object('src',a.src,'actual_n',a.n,'cached_n',b.n_plaf,'actual_value',a.total::text,'cached_value',b.v_plaf::text)) data FROM actual a JOIN marts.agg_national b USING(src)
UNION ALL SELECT 'headline_vs_profiles',jsonb_build_object('headline',(SELECT total_ron::text FROM marts.national_stats WHERE kind='spend' AND year IS NULL),'profile_authority',(SELECT sum(total_ron_split)::text FROM marts.entity_profile WHERE role='authority'),'profile_supplier',(SELECT sum(total_ron_split)::text FROM marts.entity_profile WHERE role='supplier'),'by_type',(SELECT sum(total_ron)::text FROM marts.spend_by_type WHERE kind='all'),'by_cpv',(SELECT sum(total_ron)::text FROM marts.spend_by_cpv WHERE kind='all'))
UNION ALL SELECT 'contracts_by_year',jsonb_agg(x) FROM (SELECT left(finalization_date,4) AS year,count(*) rows,count(distinct contract_id) contracts,sum(closing_value)::text total FROM marts.contract_transactions GROUP BY 1 ORDER BY 1) x
